class FakeECO(private val port: Int) {



    init {
        val PREFIX_FAKE_BPK = "zp:fakeItTillYouMakeIt-"
        embeddedServer(Netty, port = port) {
            install(ContentNegotiation) {
                json()
            }
            routing {
                get("/CardCreationCode/{cardCode}") {
                    val index = call.parameters["cardCode"]
                    call.respond(CardCreationCodeResolveResult("$PREFIX_FAKE_BPK${index}"))
                }
            }
            routing {
                delete("/CardCreationCode/{cardCode}") {
                    call.respond("")
                }
            }
            routing {
                get("/Student/{bpk}") {
                    val studentId = call.parameters["bpk"]
                    val i = studentId!!.substring(PREFIX_FAKE_BPK.length+FAKE_NONCE.length).toInt()
                    val rI = i.toRomanNumeral()
                    call.respond(
                        EcoStudentData(
                            firstname = "Mark",
                            lastname = "Nesium $rI",
                            dateOfBirth = "${1995 - (i%1990)}-10-10T00:00:00Z",
                            schoolName = "Hogwarts School of  Witchcraft adn Wizardry",
                            schoolCity = "Hogsmeade",
                            schoolZip = "987-$i",
                            schoolStreet = "RSDT 243r32",
                            schoolId = "HGRTZ-$i",
                            studentCity = "London",
                            studentZip = null,
                            studentId = studentId,
                            photo = "",
                            validUntil = "2029-10-10T00:00:00Z"
                        )
                    )
                }
            }
        }.start(wait = false)
    }

}

//https://github.com/Giroteti/roman-numerals-kata-kotlin/blob/master/src/main/kotlin/example/romanNumerals.kt
fun Int.toRomanNumeral(): String = Symbol.closestBelow(this)
    .let { symbol ->
        if (symbol != null) {
            "$symbol${(this - symbol.decimalValue).toRomanNumeral()}"
        } else {
            ""
        }
    }

fun String.toDecimal(): Int {
    return Symbol.highestStartingSymbol(this)
        .let { symbol ->
            if (symbol != null) {
                symbol.decimalValue + this.drop(symbol.name.length).toDecimal()
            } else {
                0
            }
        }
}

private enum class Symbol(val decimalValue: Int) {
    I(1),
    IV(4),
    V(5),
    IX(9),
    X(10),
    XL(40),
    L(50),
    XC(90),
    C(100),
    CD(400),
    D(500),
    CM(900),
    M(1000);

    companion object {
        fun closestBelow(value: Int) =
            values()
                .sortedByDescending { it.decimalValue }
                .firstOrNull { value >= it.decimalValue }

        fun highestStartingSymbol(value: String) =
            values()
                .sortedByDescending { it.decimalValue }
                .firstOrNull { value.startsWith(it.name) }
    }
}

private operator fun URL.plus(bindingStart: String): URL = URL(this.toExternalForm() + bindingStart)